 pub fn result(&self)->Result<&DocumentScenePlan,DocumentSceneError>{if self.cancelled{return Err(DocumentSceneError::Cancelled);}if let Some(error)=&self.owners.failure{return Err(error.clone());}if self.phase!=6{return Err(DocumentSceneError::Incomplete);}self.owners.plan.as_ref().ok_or(DocumentSceneError::Incomplete)}
